// Privacy and consent behavior: which outside servers the app talks to, the
// cookie choice, and QR codes that must never be generated by a web service.
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const H = require('./harness');

test('privacy and consent', async (t) => {
  if (!(await H.emulatorsUp())) return t.skip('Firebase emulators not running');
  await H.resetEmulators();
  const env = await H.launch();
  t.after(() => env.close());
  const A = await H.signUpAndOnboard(env, { name: 'Pat Privacy', email: 'pat.privacy@example.com' });
  const p = A.page;
  await H.clearFirstRun(p);

  await t.test('2FA and invite QR codes are drawn in the browser', async () => {
    await p.evaluate(() => open2FASetupModal());
    await p.waitForSelector('#twofa-modal img');
    assert.match(await p.getAttribute('#twofa-modal img', 'src'), /^data:image\//);
    await p.evaluate(() => close2FAModal());
    await p.evaluate(() => openInviteShareSheet());
    await p.waitForSelector('#invite-share-sheet img');
    assert.match(await p.getAttribute('#invite-share-sheet img', 'src'), /^data:image\//);
    await p.evaluate(() => document.getElementById('invite-share-sheet').remove());
  });

  await t.test('declining cookies: the only outside server is Google for the Firebase SDK', async () => {
    const D = await H.signUpAndOnboard(env, { name: 'Dee Cline', email: 'dee.cline@example.com', declineCookies: true });
    await H.clearFirstRun(D.page);
    await D.page.reload(); await D.page.waitForSelector('.nav-tab');
    await D.page.waitForTimeout(1500);
    const hosts = [...new Set(D.outside)].sort();
    assert.deepEqual(hosts, ['www.gstatic.com'], 'unexpected outside hosts: ' + hosts.join(', '));
    assert.equal(await D.page.evaluate(() => !!firebaseAnalytics), false, 'analytics not started');
  });

  await t.test('accepting cookies is what turns analytics on', async () => {
    const hosts = new Set(A.outside);
    assert.ok(hosts.has('www.googletagmanager.com'), 'analytics loads after Accept');
    for (const h of hosts) assert.match(h, /(^|\.)(gstatic|googleapis|googletagmanager|google-analytics)\.com$/, 'unexpected host ' + h);
  });

  await t.test('fonts come from our own site', async () => {
    const fonts = await p.evaluate(() => [...document.styleSheets].map((s) => s.href).filter(Boolean));
    assert.ok(fonts.some((h) => h.endsWith('/fonts/fonts.css')));
    assert.ok(!fonts.some((h) => /googleapis/.test(h)));
  });

  await t.test('cookie choice can be changed later, and declining turns analytics off', async () => {
    await p.evaluate(() => openCookieSettings());
    assert.equal(await p.isVisible('#cookie-banner'), true);
    await p.click('#cookie-banner button:has-text("Decline")');
    assert.equal(await p.evaluate(() => localStorage.getItem('ledger-cookie-consent')), 'declined');
    assert.equal(await p.isVisible('#cookie-banner'), false);
  });

  assert.deepEqual(await H.appErrors(A), []);
});
